const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open');}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter);}));
const details={ev:{title:'EV charging & DC/DC systems',label:'POWER CONVERSION',intro:'My experience includes EV onboard chargers and low-voltage DC/DC converters, spanning resonant power stages, power electronics integration and validation.',topics:[['Topology & devices','Power-factor correction, isolated CLLC conversion and SiC power devices.'],['System integration','Gate drive, protection, control interfaces and the interaction between converter stages.'],['Validation','Operating-point measurements, efficiency and loss analysis, thermal behaviour and EMI investigations.']],tools:'MATLAB/Simulink · LTspice · PSim · Altium · laboratory instrumentation'},magnetics:{title:'Transformer & inductor design',label:'MAGNETICS',intro:'Magnetic design connects electrical requirements with the physical winding arrangement. I work on models and geometry that make those trade-offs visible.',topics:[['Electrical design','Magnetising and leakage inductance, winding currents, core utilisation and operating frequency.'],['Winding arrangement','Interleaving, insulation and the relationships between leakage, copper losses and parasitic capacitance.'],['Modelling','FEM analysis and scripting to compare geometry and winding options.']],tools:'FEMM · Altair Flux 3D · MATLAB · Python'},validation:{title:'Test systems & embedded electronics',label:'VALIDATION & CONTROL',intro:'I work across test rig operation, hardware integration and embedded electronics to investigate behaviour and support repeatable converter validation.',topics:[['Test systems','HIL integration, high- and low-voltage supplies, instrumentation and signal acquisition.'],['Interfaces & control','CAN communications, restbus simulation and microcontroller-based control and protection.'],['Engineering investigations','Waveform analysis, fault reproduction and tracing observations back to their electrical causes.']],tools:'dSPACE · ETAS/INCA · Vector CAN tools · LabVIEW · C/C++'}};
const dialog=document.querySelector('#details');document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>{const d=details[button.dataset.detail];document.querySelector('#detailContent').innerHTML=`<div class="eyebrow">${d.label}</div><h2>${d.title}</h2><p>${d.intro}</p>${d.topics.map(([title,text])=>`<h3>${title}</h3><p>${text}</p>`).join('')}<div class="eyebrow">TOOLS & METHODS</div><p>${d.tools}</p>`;dialog.showModal();}));document.querySelector('#closeDetail').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});document.querySelector('#year').textContent=new Date().getFullYear();
